using System.Text.Json;
using System.Diagnostics;
using System.Runtime.InteropServices;
using Windows.Media.Control;
using Windows.Media;
using Windows.Storage.Streams;
class Program {
 [DllImport("user32.dll")] static extern IntPtr GetForegroundWindow();
 [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr hwnd,out uint pid);
 static string lastApp="";static string? artworkApp=null;static readonly object gate=new();static GlobalSystemMediaTransportControlsSessionManager? manager;
 record Artwork(string Key,string Data,DateTime Attempt);
 static readonly Dictionary<string,Artwork> art=new();
 static void Emit(object obj){lock(gate)Console.WriteLine(JsonSerializer.Serialize(obj));}
 static void Error(string component,Exception e)=>Emit(new{type="error",component,code=e.HResult,message=e.Message});
 static object? AppInfo(Process p){try{var exe=p.MainModule?.FileName;return new{id=(exe??p.ProcessName).ToLowerInvariant(),name=p.ProcessName,path=exe??""};}catch{try{return new{id=p.ProcessName.ToLowerInvariant(),name=p.ProcessName,path=""};}catch{return null;}}}
 static void Front(){try{GetWindowThreadProcessId(GetForegroundWindow(),out uint pid);using var p=Process.GetProcessById((int)pid);var a=AppInfo(p);var id=p.Id+":"+p.ProcessName;if(a!=null&&id!=lastApp){lastApp=id;Emit(new{type="front-app",app=a});}}catch{}}
 static void Apps(){var apps=new List<object>();foreach(var p in Process.GetProcesses()){using(p){try{if(p.MainWindowHandle!=IntPtr.Zero&&AppInfo(p)is object a)apps.Add(a);}catch{}}}Emit(new{type="apps",apps});}
 static async Task Main(){try{manager=await GlobalSystemMediaTransportControlsSessionManager.RequestAsync();}catch(Exception e){Error("media-init",e);}
 _=Task.Run(async()=>{while(await Console.In.ReadLineAsync()is string line){string? action=null,requestId=null;try{using var doc=JsonDocument.Parse(line);var r=doc.RootElement;action=r.GetProperty("action").GetString();if(action=="list-apps"){Apps();continue;}if(action=="select-source"){artworkApp=r.GetProperty("targetId").GetString();continue;}requestId=r.TryGetProperty("requestId",out var rid)?rid.GetString():null;var target=r.TryGetProperty("targetId",out var tid)?tid.GetString():null;var s=target!=null?manager?.GetSessions().FirstOrDefault(s=>s.SourceAppUserModelId==target):manager?.GetCurrentSession();bool ok=false;if(s!=null){switch(action){case"play":ok=await s.TryPlayAsync();break;case"pause":ok=await s.TryPauseAsync();break;case"toggle":ok=await s.TryTogglePlayPauseAsync();break;case"next":ok=await s.TrySkipNextAsync();break;case"previous":ok=await s.TrySkipPreviousAsync();break;case"seek":ok=await s.TryChangePlaybackPositionAsync((long)(Math.Max(0,r.GetProperty("value").GetDouble())*10000000));break;case"shuffle":ok=await s.TryChangeShuffleActiveAsync(r.GetProperty("value").GetBoolean());break;case"repeat":ok=await s.TryChangeAutoRepeatModeAsync(r.GetProperty("value").GetString()switch{"one"=>MediaPlaybackAutoRepeatMode.Track,"all"=>MediaPlaybackAutoRepeatMode.List,_=>MediaPlaybackAutoRepeatMode.None});break;}}Emit(new{type="result",action,ok,requestId});}catch(Exception e){Error("command",e);Emit(new{type="result",action,ok=false,requestId});}}Environment.Exit(0);});
 while(true){try{Front();if(manager!=null)await Poll();}catch(Exception e){Error("media-poll",e);}await Task.Delay(900);}}
 static async Task<object> Track(GlobalSystemMediaTransportControlsSession s,bool includeArtwork){var p=await s.TryGetMediaPropertiesAsync();var info=s.GetPlaybackInfo();var timeline=s.GetTimelineProperties();var c=info.Controls;var app=s.SourceAppUserModelId;string key=p.Title+"|"+p.Artist;art.TryGetValue(app,out var cached);if(cached?.Key!=key)cached=new(key,"",DateTime.MinValue);
 if(includeArtwork&&cached.Data==""&&(DateTime.UtcNow-cached.Attempt).TotalSeconds>3){var image="";try{if(p.Thumbnail!=null){using var input=await p.Thumbnail.OpenReadAsync();if(input.Size<=2000000){using var reader=new DataReader(input);await reader.LoadAsync((uint)input.Size);var data=new byte[(int)input.Size];reader.ReadBytes(data);var mime=input.ContentType;if(mime is "image/jpeg" or "image/png" or "image/webp")image="data:"+mime+";base64,"+Convert.ToBase64String(data);}}}catch{}cached=new(key,image,DateTime.UtcNow);}art[app]=cached;
 return new{sourceId="system:"+app,provider=app,title=p.Title,artist=p.Artist,artwork=includeArtwork?cached.Data:"",playing=info.PlaybackStatus==GlobalSystemMediaTransportControlsSessionPlaybackStatus.Playing,position=Math.Max(0,timeline.Position.TotalSeconds),duration=Math.Max(0,timeline.EndTime.TotalSeconds),shuffle=info.IsShuffleActive,repeat=info.AutoRepeatMode?.ToString()switch{"Track"=>"one","List"=>"all","None"=>"off",_=>null},app,mediaType=info.PlaybackType==MediaPlaybackType.Video?"video":"music",capabilities=new{toggle=c.IsPlayPauseToggleEnabled,play=c.IsPlayEnabled,pause=c.IsPauseEnabled,autoPause=c.IsPauseEnabled&&c.IsPlayEnabled,next=c.IsNextEnabled,previous=c.IsPreviousEnabled,seek=c.IsPlaybackPositionEnabled,shuffle=c.IsShuffleEnabled,repeat=c.IsRepeatEnabled}};
 }
 static async Task Poll(){var sessions=manager!.GetSessions().GroupBy(s=>s.SourceAppUserModelId).Select(g=>g.First()).Take(32).ToArray();var rows=new List<object>();object? current=null;var currentApp=manager.GetCurrentSession()?.SourceAppUserModelId;foreach(var s in sessions){try{var row=await Track(s,s.SourceAppUserModelId==(artworkApp??currentApp));rows.Add(row);if(s.SourceAppUserModelId==currentApp)current=row;}catch{}}foreach(var id in art.Keys.Except(sessions.Select(s=>s.SourceAppUserModelId)).ToArray())art.Remove(id);Emit(new{type="sources",sources=rows});Emit(new{type="track",track=current});}
}
